// GENERATED by services/setup/scripts/sync-machine.mjs from shell/src/components/setup-wizard. Do not edit.
// The setup state machine: enforces states.ts, persists every transition, and tells the host which entry/exit
// actions to run. It performs no side effects itself; the host (shell UI talking to the setup service) runs the
// actions and reports back with events (WORK_DONE, WORK_FAILED, NETWORK_LOST …).
import { SetupCheckpointManager } from './SetupCheckpointManager.ts'
import { deserialize, SCHEMA_VERSION, serialize, type Checkpoint, type SetupPersistence, type SetupSnapshot } from './SetupPersistence.ts'
import { validate } from './SetupValidation.ts'
import {
  flowFor, isMain, POINT_OF_NO_RETURN, SIDE_RULES, SPECS, WORK_STATES,
  type MainState, type SetupEvent, type SetupMode, type SetupState, type SideState,
} from './states.ts'

export interface TransitionResult {
  ok: boolean
  state: SetupState
  /** Why the event was refused, or validation errors per field. */
  error?: string
  fieldErrors?: Record<string, string>
  /** Actions the host runs now, in order: the left state's exit actions, then the entered state's entry actions. */
  actions: string[]
  /** For RETRYING: wait this long, then send RETRY_NOW (or TIMEOUT). */
  retryInMs?: number
}

export interface MachineOptions { mode: SetupMode; persistence: SetupPersistence; now?: () => number; online?: () => boolean }

export class SetupStateMachine {
  private snap!: SetupSnapshot
  private cps = new SetupCheckpointManager()
  private listeners = new Set<(s: SetupSnapshot) => void>()
  private readonly now: () => number
  private readonly online: () => boolean
  private readonly flow: MainState[]
  /** Why start() went to recovery (corrupt state file, interrupted work …), for the recovery screen. */
  startReason: 'fresh' | 'resumed' | 'interrupted' | 'corrupt' | 'version' | 'completed' = 'fresh'

  private readonly o: MachineOptions

  constructor(o: MachineOptions) {
    this.o = o
    this.now = o.now ?? Date.now
    this.online = o.online ?? (() => true)
    this.flow = flowFor(o.mode)
  }

  get state(): SetupState { return this.snap.state }
  get snapshot(): Readonly<SetupSnapshot> { return this.snap }
  get checkpoints(): readonly Checkpoint[] { return this.cps.all() }
  subscribe(fn: (s: SetupSnapshot) => void) { this.listeners.add(fn); return () => this.listeners.delete(fn) }

  /** Load persisted state. An interrupted unattended step (power loss mid-install) never silently re-runs:
   *  it opens RECOVERY_MODE so the person chooses Resume, Retry, Restore or Roll back. */
  async start(): Promise<TransitionResult> {
    const loaded = deserialize(await this.o.persistence.load())
    if (!loaded.ok) {
      this.snap = this.fresh()
      if (loaded.reason !== 'empty') {
        // A damaged state file: never guess. Recovery with nothing restorable (the disk may already be written).
        this.startReason = loaded.reason
        this.snap.state = 'RECOVERY_MODE'; this.snap.resumeTo = 'INITIALIZING'; this.snap.lastError = `setup state was ${loaded.reason === 'corrupt' ? 'damaged' : 'from another version'}`
        await this.persist()
        return { ok: true, state: this.snap.state, actions: [] }
      }
      await this.persist()
      return { ok: true, state: 'INITIALIZING', actions: [...SPECS.INITIALIZING.entry] }
    }
    this.snap = loaded.snapshot
    this.cps = new SetupCheckpointManager(this.snap.checkpoints)
    if (this.snap.state === 'SETUP_COMPLETED') { this.startReason = 'completed'; return { ok: true, state: this.snap.state, actions: [] } }
    const s = this.snap.state
    const interrupted = (isMain(s) && WORK_STATES.includes(s) && s !== 'INITIALIZING') || s === 'RETRYING' || s === 'ROLLING_BACK'
    if (interrupted) {
      this.startReason = 'interrupted'
      this.snap.resumeTo = isMain(s) ? s : this.snap.resumeTo
      this.snap.lastError = s === 'ROLLING_BACK' ? 'a rollback was interrupted' : 'setup was interrupted (restart or power loss)'
      this.snap.state = 'RECOVERY_MODE'
      await this.persist()
      return { ok: true, state: 'RECOVERY_MODE', actions: ['collectLogs'] }
    }
    this.startReason = 'resumed'
    return { ok: true, state: s, actions: isMain(s) ? [...SPECS[s].entry] : [] }
  }

  setAnswer(key: string, value: unknown) {
    this.snap.answers[key] = value
    void this.persist()
  }

  /** Attach the host's rollback handle (snapshot taken, package transaction opened) to the latest checkpoint. */
  async attachRollback(rollback: NonNullable<Checkpoint['rollback']>) {
    const cp = this.cps.latest(); if (!cp) return
    this.cps.attachRollback(cp.id, rollback); await this.persist()
  }

  async send(e: SetupEvent): Promise<TransitionResult> {
    const r = this.decide(e)
    if (r.ok) await this.persist()
    return r
  }

  // ---- rules ----
  private decide(e: SetupEvent): TransitionResult {
    const s = this.snap.state
    return isMain(s) ? this.fromMain(s, e) : this.fromSide(s, e)
  }

  private refuse(error: string): TransitionResult { return { ok: false, state: this.snap.state, error, actions: [] } }
  private idx(s: MainState) { return this.flow.indexOf(s) }
  private nextOf(s: MainState): MainState | undefined { return this.flow[this.idx(s) + 1] }
  private prevOf(s: MainState): MainState | undefined { return this.flow[this.idx(s) - 1] }
  private beforeNoReturn(s: MainState) { return this.idx(s) < this.idx(POINT_OF_NO_RETURN) }

  private enter(to: SetupState, from: SetupState, extra: Partial<TransitionResult> = {}): TransitionResult {
    const actions = [...(isMain(from) && from !== to ? SPECS[from].exit : []), ...(isMain(to) && from !== to ? SPECS[to].entry : [])]
    // Attempts count per step: reset when the flow moves on to another step, kept across RETRYING/PAUSED/recovery
    // round trips back into the same step (otherwise a failing step would retry forever).
    if (isMain(to) && isMain(from) && to !== from) this.snap.attempts = 0
    this.snap.state = to
    if (isMain(to)) this.snap.lastError = null
    return { ok: true, state: to, actions, ...extra }
  }

  /** Forward into `to`: if it needs the internet and there is none, wait for the network first. */
  private forward(from: MainState, to: MainState): TransitionResult {
    const spec = SPECS[from]
    if (spec.checkpoint || spec.effect !== 'none' || SPECS[to].effect !== 'none') this.cps.take(from, this.snap.answers, this.now())
    if (SPECS[to].network === 'required' && !this.online()) {
      this.snap.resumeTo = to
      return this.enter('WAITING_FOR_NETWORK', from)
    }
    return this.enter(to, from)
  }

  private fromMain(s: MainState, e: SetupEvent): TransitionResult {
    const spec = SPECS[s]
    const work = WORK_STATES.includes(s)
    switch (e.type) {
      case 'NEXT': {
        if (work) return this.refuse(`${s} finishes on its own`)
        const errs = validate(spec.requires, this.snap.answers)
        if (Object.keys(errs).length) return { ...this.refuse('some answers are missing or invalid'), fieldErrors: errs }
        const to = this.nextOf(s); if (!to) return this.refuse('setup is complete')
        return this.forward(s, to)
      }
      case 'WORK_DONE': {
        if (!work) return this.refuse(`${s} waits for the person`)
        const to = this.nextOf(s); if (!to) return this.refuse('setup is complete')
        return this.forward(s, to)
      }
      case 'BACK': {
        const to = this.prevOf(s)
        if (!to || to === 'INITIALIZING') return this.refuse('this is the first step')
        if (!this.beforeNoReturn(s)) return this.refuse('the system is being changed; use recovery instead of going back')
        return this.enter(to, s)
      }
      case 'GOTO': {
        // Edit an earlier answer from the review: only backwards, only before the point of no return.
        if (!this.flow.includes(e.to)) return this.refuse(`${e.to} is not part of ${this.o.mode} setup`)
        if (this.idx(e.to) >= this.idx(s)) return this.refuse('only earlier steps can be revisited')
        if (!this.beforeNoReturn(s)) return this.refuse('the system is being changed; use recovery instead of going back')
        return this.enter(e.to, s)
      }
      case 'WORK_FAILED': case 'TIMEOUT': {
        if (e.type === 'TIMEOUT' && spec.timeoutMs === 0) return this.refuse(`${s} has no timeout`)
        const error = e.type === 'TIMEOUT' ? `${s} timed out` : e.error
        this.snap.lastError = error
        this.snap.resumeTo = s
        this.snap.attempts++
        const retryable = e.type === 'TIMEOUT' || e.retryable !== false
        if (retryable && this.snap.attempts <= spec.retry.max) {
          const retryInMs = spec.retry.backoffMs * spec.retry.factor ** (this.snap.attempts - 1)
          const r = this.enter('RETRYING', s, { retryInMs }); this.snap.lastError = error; return r
        }
        const r = this.enter(spec.onExhausted, s); this.snap.lastError = error; return r
      }
      case 'NETWORK_LOST':
        if (spec.network !== 'required') return { ok: true, state: s, actions: [] }   // optional: keep going offline
        this.snap.resumeTo = s; return this.enter('WAITING_FOR_NETWORK', s)
      case 'PAUSE':
        if (s === 'INSTALLING_OS') return this.refuse('the disk is being written; it cannot be paused safely')
        this.snap.resumeTo = s; return this.enter('PAUSED', s)
      case 'NEED_USER': this.snap.resumeTo = s; return this.enter('WAITING_FOR_USER', s)
      case 'NEED_APPROVAL': this.snap.resumeTo = s; return this.enter('WAITING_FOR_ADMIN_APPROVAL', s)
      case 'ENTER_RECOVERY': this.snap.resumeTo = s; this.snap.lastError = e.reason; return this.enter('RECOVERY_MODE', s, { actions: ['collectLogs'] })
      case 'CANCEL':
        if (s === 'INSTALLING_OS') return this.refuse('the disk is being written; cancelling now would leave it unusable')
        if (s === 'SETUP_COMPLETED') return this.refuse('setup is complete')
        this.snap.resumeTo = s; return this.enter('CANCELLED', s)
      default: return this.refuse(`${e.type} is not allowed in ${s}`)
    }
  }

  private fromSide(s: SideState, e: SetupEvent): TransitionResult {
    const target = SIDE_RULES[s][e.type]
    if (!target) return this.refuse(`${e.type} is not allowed in ${s}`)
    if (e.type === 'RESTART_SETUP') {
      // Answers and checkpoints are dropped; a disk that was already written stays as it is (never "restored").
      const keep = this.snap.mode
      this.snap = { ...this.fresh(), mode: keep }
      this.cps = new SetupCheckpointManager(this.snap.checkpoints)
      return this.enter('INITIALIZING', s)
    }
    if (e.type === 'RESTORE_CHECKPOINT') {
      const cp = this.cps.find(e.checkpointId); if (!cp) return this.refuse('no such checkpoint')
      const next = this.nextOf(cp.state); if (!next) return this.refuse('nothing to resume after that checkpoint')
      this.snap.answers = structuredClone(cp.answers)
      // Going back over a destructive step means it runs again: the person must confirm the disk again.
      if (this.idx(next) <= this.idx('INSTALLING_OS') && this.flow.includes('INSTALLING_OS')) delete this.snap.answers.diskConfirmed
      this.cps.truncateAfter(cp.id)
      this.snap.attempts = 0
      // Unattended steps restart from their checkpoint; question steps reopen for the person.
      return this.enter(next, s)
    }
    if (e.type === 'ROLLBACK_DONE') {
      const cp = this.rollbackCheckpoint()
      this.snap.attempts = 0
      if (cp) { this.snap.answers = structuredClone(cp.answers); this.cps.truncateAfter(cp.id); this.snap.resumeTo = this.nextOf(cp.state) ?? this.snap.resumeTo }
    }
    if (e.type === 'ROLLBACK' && !this.rollbackCheckpoint()) return this.refuse('no verified rollback point covers the changes made')
    if (e.type === 'ROLLBACK_FAILED') this.snap.lastError = e.error
    if (e.type === 'DENIED') this.snap.lastError = e.reason
    if (target === '@resume') {
      const to = this.snap.resumeTo ?? 'INITIALIZING'
      // Resuming something that needs the internet while offline: keep waiting instead.
      if (SPECS[to].network === 'required' && !this.online() && s !== 'WAITING_FOR_NETWORK') return this.enter('WAITING_FOR_NETWORK', s)
      if (SPECS[to].network === 'required' && !this.online()) return this.refuse('still offline')
      // Re-enter the interrupted state: its entry actions run again (they are idempotent by contract).
      const r = this.enter(to, s); return { ...r, actions: [...SPECS[to].entry] }
    }
    return this.enter(target, s)
  }

  /** The newest checkpoint with a verified rollback handle taken at or before the step being undone. */
  rollbackCheckpoint(): Checkpoint | undefined {
    const at = this.snap.resumeTo; if (!at) return undefined
    return [...this.cps.all()].reverse().find((c) => c.rollback?.verified && this.idx(c.state) < this.idx(at))
  }

  // ---- persistence ----
  private fresh(): SetupSnapshot {
    return { version: SCHEMA_VERSION, mode: this.o.mode, state: 'INITIALIZING', resumeTo: null, answers: {}, attempts: 0, lastError: null, checkpoints: [], updatedAt: this.now() }
  }
  private async persist() {
    this.snap.checkpoints = this.cps.all() as Checkpoint[]
    this.snap.updatedAt = this.now()
    await this.o.persistence.save(serialize(this.snap))
    for (const fn of this.listeners) fn(this.snap)
  }
}
